window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a1da1a354b39c4b9"]={"versions": [{"id": "FIG-a1da1a354b39c4b9", "releases": ["R4.3.1", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitekturdiagramm der AUTOSAR Classic Platform zur Einordnung des Basissoftware-Moduls Vehicle-2-X Facilities (V2xFac) in den AUTOSAR-Gesamtaufbau. Die Schichten gliedern sich vertikal von oben nach unten in Application, RTE (Runtime Environment), Services (unterteilt in V2X Services und Communication Services), Communication HW abstraction sowie Communication Drivers. Die Komponente Vehicle-2-X Facilities ist durch eine gelb gestrichelte Umrandung als Fokus des Dokuments hervorgehoben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application</strong>: Beinhaltet die Software-Komponenten VDP (Vehicle Data Provider), V2xProxy sowie POTI (Position and Time).</li>\n<li><strong>RTE</strong>: Bildet die Trennschicht zwischen Application und der darunterliegenden Basissoftware.</li>\n<li><strong>V2X Services</strong>:</li>\n<li><code>Vehicle-2-X Facilities</code>: Modul der Facilities-Schicht, gelb gestrichelt umrandet, direkt unter der RTE und oberhalb des Basic-Transport-Moduls platziert.</li>\n<li><code>Vehicle-2-X Basic Transport</code>: Protokollschicht unterhalb von Vehicle-2-X Facilities.</li>\n<li><code>Vehicle-2-X GeoNetworking</code>: Netzwerk-/Routing-Schicht unterhalb von Vehicle-2-X Basic Transport.</li>\n<li><code>Vehicle-2-X Management</code>: Vertikal durchgängiges Management-Modul parallel zum Protokollstapel aus Facilities, Basic Transport und GeoNetworking.</li>\n<li><strong>Communication Services</strong>: Parallele Service-Domäne neben den V2X Services.</li>\n<li><strong>Communication HW abstraction</strong>: Hardware-Abstraktionsschicht unterhalb der Service-Schichten.</li>\n<li><strong>Communication Drivers</strong>: Treiber-Schicht als unterste Software-Ebene.</li>\n</ul>\n<p class=\"fig-p\">Diskrete Interaktions- oder Verbindungspfeile sind im Blockdiagramm nicht dargestellt; Schnittstellenbeziehungen ergeben sich implizit aus der Schichtung und Nachbarschaft der Blöcke.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Blockschaltbild ohne Sequenzabläufe, Kontrollflusspfeile oder dynamische Zustandsübergänge. Die Nachrichtenverarbeitung verläuft konzeptionell vertikal durch den V2X-Protokollstapel (Application <-> RTE <-> Vehicle-2-X Facilities <-> Vehicle-2-X Basic Transport <-> Vehicle-2-X GeoNetworking <-> Communication HW abstraction <-> Communication Drivers), orchestriert bzw. konfiguriert durch das Vehicle-2-X Management.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturübersicht zur Verortung von Vehicle-2-X Facilities innerhalb des AUTOSAR BSW Stacks. Das Modul ist der V2X-Services-Schicht zugeordnet und interagiert über die RTE mit applikativen SW-Cs (wie POTI, VDP, V2xProxy) sowie nach unten mit dem V2X Basic Transport Modul. Integratoren entnehmen dem Diagramm die modulare Schichtung und die Trennung zwischen Management- und Datenpfad im V2X-Subsystem.</p>"}, {"id": "FIG-65e1d827082388bb", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitekturdiagramm der AUTOSAR Classic Platform zur Einordnung des Basissoftware-Moduls Vehicle-2-X Facilities (V2xFac) in den AUTOSAR-Gesamtaufbau. Die Schichten gliedern sich vertikal von oben nach unten in Application, RTE (Runtime Environment), Services (unterteilt in V2X Services und Communication Services), Communication HW abstraction sowie Communication Drivers. Die Komponente Vehicle-2-X Facilities ist durch eine gelb gestrichelte Umrandung als Fokus des Dokuments hervorgehoben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application</strong>: Beinhaltet die Software-Komponenten VDP (Vehicle Data Provider), V2xProxy sowie POTI (Position and Time).</li>\n<li><strong>RTE</strong>: Bildet die Trennschicht zwischen Application und der darunterliegenden Basissoftware.</li>\n<li><strong>V2X Services</strong>:</li>\n<li><code>Vehicle-2-X Facilities</code>: Modul der Facilities-Schicht, gelb gestrichelt umrandet, direkt unter der RTE und oberhalb des Basic-Transport-Moduls platziert.</li>\n<li><code>Vehicle-2-X Basic Transport</code>: Protokollschicht unterhalb von Vehicle-2-X Facilities.</li>\n<li><code>Vehicle-2-X GeoNetworking</code>: Netzwerk-/Routing-Schicht unterhalb von Vehicle-2-X Basic Transport.</li>\n<li><code>Vehicle-2-X Management</code>: Vertikal durchgängiges Management-Modul parallel zum Protokollstapel aus Facilities, Basic Transport und GeoNetworking.</li>\n<li><strong>Communication Services</strong>: Parallele Service-Domäne neben den V2X Services.</li>\n<li><strong>Communication HW abstraction</strong>: Hardware-Abstraktionsschicht unterhalb der Service-Schichten.</li>\n<li><strong>Communication Drivers</strong>: Treiber-Schicht als unterste Software-Ebene.</li>\n</ul>\n<p class=\"fig-p\">Diskrete Interaktions- oder Verbindungspfeile sind im Blockdiagramm nicht dargestellt; Schnittstellenbeziehungen ergeben sich implizit aus der Schichtung und Nachbarschaft der Blöcke.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Blockschaltbild ohne Sequenzabläufe, Kontrollflusspfeile oder dynamische Zustandsübergänge. Die Nachrichtenverarbeitung verläuft konzeptionell vertikal durch den V2X-Protokollstapel (Application <-> RTE <-> Vehicle-2-X Facilities <-> Vehicle-2-X Basic Transport <-> Vehicle-2-X GeoNetworking <-> Communication HW abstraction <-> Communication Drivers), orchestriert bzw. konfiguriert durch das Vehicle-2-X Management.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturübersicht zur Verortung von Vehicle-2-X Facilities innerhalb des AUTOSAR BSW Stacks. Das Modul ist der V2X-Services-Schicht zugeordnet und interagiert über die RTE mit applikativen SW-Cs (wie POTI, VDP, V2xProxy) sowie nach unten mit dem V2X Basic Transport Modul. Integratoren entnehmen dem Diagramm die modulare Schichtung und die Trennung zwischen Management- und Datenpfad im V2X-Subsystem.</p>"}, {"id": "FIG-9eaa33c555a983f3", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitekturdiagramm der AUTOSAR Classic Platform zur Einordnung des Basissoftware-Moduls Vehicle-2-X Facilities (V2xFac) in den AUTOSAR-Gesamtaufbau. Die Schichten gliedern sich vertikal von oben nach unten in Application, RTE (Runtime Environment), Services (unterteilt in V2X Services und Communication Services), Communication HW abstraction sowie Communication Drivers. Die Komponente Vehicle-2-X Facilities ist durch eine gelb gestrichelte Umrandung als Fokus des Dokuments hervorgehoben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application</strong>: Beinhaltet die Software-Komponenten VDP (Vehicle Data Provider), V2xProxy sowie POTI (Position and Time).</li>\n<li><strong>RTE</strong>: Bildet die Trennschicht zwischen Application und der darunterliegenden Basissoftware.</li>\n<li><strong>V2X Services</strong>:</li>\n<li><code>Vehicle-2-X Facilities</code>: Modul der Facilities-Schicht, gelb gestrichelt umrandet, direkt unter der RTE und oberhalb des Basic-Transport-Moduls platziert.</li>\n<li><code>Vehicle-2-X Basic Transport</code>: Protokollschicht unterhalb von Vehicle-2-X Facilities.</li>\n<li><code>Vehicle-2-X GeoNetworking</code>: Netzwerk-/Routing-Schicht unterhalb von Vehicle-2-X Basic Transport.</li>\n<li><code>Vehicle-2-X Management</code>: Vertikal durchgängiges Management-Modul parallel zum Protokollstapel aus Facilities, Basic Transport und GeoNetworking.</li>\n<li><strong>Communication Services</strong>: Parallele Service-Domäne neben den V2X Services.</li>\n<li><strong>Communication HW abstraction</strong>: Hardware-Abstraktionsschicht unterhalb der Service-Schichten.</li>\n<li><strong>Communication Drivers</strong>: Treiber-Schicht als unterste Software-Ebene.</li>\n</ul>\n<p class=\"fig-p\">Diskrete Interaktions- oder Verbindungspfeile sind im Blockdiagramm nicht dargestellt; Schnittstellenbeziehungen ergeben sich implizit aus der Schichtung und Nachbarschaft der Blöcke.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Blockschaltbild ohne Sequenzabläufe, Kontrollflusspfeile oder dynamische Zustandsübergänge. Die Nachrichtenverarbeitung verläuft konzeptionell vertikal durch den V2X-Protokollstapel (Application <-> RTE <-> Vehicle-2-X Facilities <-> Vehicle-2-X Basic Transport <-> Vehicle-2-X GeoNetworking <-> Communication HW abstraction <-> Communication Drivers), orchestriert bzw. konfiguriert durch das Vehicle-2-X Management.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturübersicht zur Verortung von Vehicle-2-X Facilities innerhalb des AUTOSAR BSW Stacks. Das Modul ist der V2X-Services-Schicht zugeordnet und interagiert über die RTE mit applikativen SW-Cs (wie POTI, VDP, V2xProxy) sowie nach unten mit dem V2X Basic Transport Modul. Integratoren entnehmen dem Diagramm die modulare Schichtung und die Trennung zwischen Management- und Datenpfad im V2X-Subsystem.</p>"}, {"id": "FIG-d10834a00289f971", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitekturdiagramm der AUTOSAR Classic Platform zur Einordnung des Basissoftware-Moduls V2X Facilities (V2xFac) in den Off-Board-Kommunikationsstack. Die Schichten gliedern sich von oben nach unten in Application Layer, Runtime Environment (RTE), Off-board Communication Services, Communication Hardware Abstraction sowie Communication Drivers. V2X Facilities bildet zusammen mit dem V2X Data Manager die oberste Funktionsebene des V2X-Dienstestapels unterhalb der RTE.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Beinhaltet die Anwendungskomponenten POTI, VDP, V2xProxy und eine generische SW-C.</li>\n<li><strong>Runtime Environment (RTE)</strong>: Vermittelt zwischen Application Layer und Basissoftware.</li>\n<li><strong>Off-board Communication Services</strong>:</li>\n<li><code>V2X Management</code>: Vertikales Modul über die gesamte Höhe der Off-board Communication Services zur bereichsübergreifenden Verwaltung.</li>\n<li><code>V2X Data Manager</code>: Modul oberhalb von V2X Facilities mit direkter Anbindung an die RTE.</li>\n<li><code>V2X Facilities</code>: L-förmig geschnittenes Modul, das unterhalb des V2X Data Managers liegt und sich links daran vorbei direkt an die RTE erstreckt.</li>\n<li><code>V2X Basic Transport Protocol</code>: Protokollschicht unterhalb von V2X Facilities.</li>\n<li><code>V2X Geo Networking</code>: Netzwerk-Schicht unterhalb des Basic Transport Protocols.</li>\n<li><strong>Communication Hardware Abstraction</strong>: Schicht zur Abstraktion der Kommunikations-Hardware.</li>\n<li><strong>Communication Drivers</strong>: Treiber-Schicht zur Hardwareanbindung.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen sind rein über Schichtgrenzen und Modulnachbarschaften ohne Pfeile abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne dynamische Abläufe oder Nachrichtensequenzen. Der Datenfluss verläuft vertikal zwischen Application Layer, RTE, V2X Data Manager bzw. V2X Facilities, V2X Basic Transport Protocol, V2X Geo Networking und den hardwarenahen Schichten, flankiert von Kontroll- und Konfigurationsflüssen durch das V2X Management.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verortung der V2X-Basissoftware innerhalb der AUTOSAR Classic Platform. Entwickler und Integratoren müssen berücksichtigen, dass V2X Facilities sowohl Schnittstellen zur RTE als auch zum V2X Data Manager und zum V2X Basic Transport Protocol besitzt, während V2X Management als Querschnittsmodul agiert.</p>"}], "trans": [{"from": "FIG-a1da1a354b39c4b9", "to": "FIG-65e1d827082388bb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-65e1d827082388bb", "to": "FIG-a1da1a354b39c4b9", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a1da1a354b39c4b9", "to": "FIG-9eaa33c555a983f3", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9eaa33c555a983f3", "to": "FIG-d10834a00289f971", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuaufnahme der BSW-Komponente V2X Data Manager oberhalb von V2X Facilities</li>\n<li>L-förmige Erweiterung des Modulblocks V2X Facilities zur direkten Anbindung an die RTE neben dem V2X Data Manager</li>\n<li>Umbenennung des Servicelayers von „V2X Services“ und „Communication Services“ zu „Off-board Communication Services“</li>\n<li>Hinzufügung der Anwendungskomponente SW-C in der Application Layer</li>\n<li>Umbenennung von „Vehicle-2-X Facilities“ in „V2X Facilities“, „Vehicle-2-X Basic Transport“ in „V2X Basic Transport Protocol“, „Vehicle-2-X GeoNetworking“ in „V2X Geo Networking“ und „Vehicle-2-X Management“ in „V2X Management“</li>\n<li>Ausschreibung von „Application“ zu „Application Layer“, „RTE“ zu „Runtime Environment (RTE)“ und „Communication HW abstraction“ zu „Communication Hardware Abstraction“</li>\n<li>Entfernung der gelb gestrichelten Hervorhebung um den Facilities-Block</li>\n</ul>"}]};
